const PlatformColors: Record<string, string> = {
  instagram: '#E4405F',
  tiktok: '#000000',
  youtube: '#FF0000',
  'x (twitter)': '#1DA1F2',
  'x': '#1DA1F2',
  twitter: '#1DA1F2',
  spotify: '#1DB954',
  facebook: '#1877F2',
  linkedin: '#0A66C2',
  snapchat: '#FFFC00',
};

export const PlatformIcon = memo(function PlatformIcon({ platform, size = 20, className = '' }: PlatformIconProps) {
  const normalizedPlatform = platform.toLowerCase();
  const color = PlatformColors[normalizedPlatform] || '#888';

  const icons: Record<string, React.ReactNode> = {
    instagram: <InstagramIcon size={size} />,
    tiktok: <TikTokIcon size={size} />,
    youtube: <YouTubeIcon size={size} />,
    'x (twitter)': <XIcon size={size} />,
    'x': <XIcon size={size} />,
    twitter: <XIcon size={size} />,
    spotify: <SpotifyIcon size={size} />,
    facebook: <FacebookIcon size={size} />,
    linkedin: <LinkedInIcon size={size} />,
    snapchat: <SnapchatIcon size={size} />,
  };

  const icon = icons[normalizedPlatform] || icons['instagram'];

  return (
    <span className={className} style={{ color, display: 'inline-flex' }}>
      {icon}
    </span>
  );
});

export const PlatformIconWithBg = memo(function PlatformIconWithBg({
  platform,
  size = 36,
  iconSize = 18,
  className = ''
}: PlatformIconProps & { iconSize?: number }) {
  const normalizedPlatform = platform.toLowerCase();
  const color = PlatformColors[normalizedPlatform] || '#888';

  return (
    <div
      className={className}
      style={{
        width: size,
        height: size,
        borderRadius: 8,
        background: color + '20',
        border: '1px solid ' + color + '40',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <PlatformIcon platform={platform} size={iconSize} />
    </div>
  );
});

export default PlatformIcon;
